def f(xs):
    if not xs:
        return []
    return xs[2:] if xs[0] > xs[-1] else xs[:-2]

def f(xs):
    ys = xs[:]
    if len(ys) >= 4:
        ys[0], ys[3] = ys[3], ys[0]
    return ys

def f(xs):
    n = xs[-1] if xs else 0
    return xs[n - 1:n] if 1 <= n <= len(xs) else []

def f(xs):
    if not xs:
        return []
    lo, hi = min(xs), max(xs)
    return [x for x in xs if x != lo and x != hi]

def f(xs):
    out = []
    for x in xs:
        product = 1
        for digit in str(abs(x)).zfill(2):
            product *= int(digit)
        out.append(product)
    return out

def f(xs):
    values = sorted(set(xs))
    return [values[-2]] if len(values) >= 2 else []

def f(xs):
    out = []
    for a, b in zip(xs, reversed(xs)):
        out.extend((a, b))
    return out

def f(xs):
    multiplier = 2 if len(xs) % 2 == 0 else 3
    return [multiplier * x for x in xs]

def f(xs):
    counts = {}
    out = []
    for x in xs:
        counts[x] = counts.get(x, 0) + 1
        out.append(counts[x])
    return out

def f(xs):
    if len(xs) < 2:
        return []
    n, value = xs[:2]
    return [value] * min(max(n, 0), 10000)
